                ci_low = d[k][sk].get('ci_low', d[k][sk].get('ci_lo'))
                ci_high = d[k][sk].get('ci_high', d[k][sk].get('ci_hi'))
                print(f'{k}/{sk}: CI=[{ci_low}, {ci_high}]')
            else:
                print(f'{k}/{sk}: {d[k][sk]}')
    else:
        print(f'{k}: {d[k]}')
"

