import json
d = json.load(open('/root/autodl-tmp/pacs/analysis_output/supplementary_stats.json'))
print('Top keys:', list(d.keys()))
print('BH-FDR summary:', d['bh_fdr_correction']['summary'])
print('n_tests:', d['bh_fdr_correction']['n_tests'])

# Count significant tests by category
cats = {}
for t in d['bh_fdr_correction']['tests']:
    cat = t['category']
    if cat not in cats:
        cats[cat] = {'total': 0, 'bh_sig': 0, 'bonf_sig': 0}
    cats[cat]['total'] += 1
    if t['bh_significant']:
        cats[cat]['bh_sig'] += 1
    if t['bonferroni_significant']:
        cats[cat]['bonf_sig'] += 1
for cat, v in cats.items():
    print(f'  {cat}: {v}')
"

